svg.script:
(function(){
var svg=document.currentScript&&document.currentScript.ownerSVGElement;if(!svg)return;
var mq=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)');
if(mq&&mq.matches){try{svg.pauseAnimations();}catch(e){}
 Array.prototype.slice.call(svg.querySelectorAll('animate,animateMotion,animateTransform')).forEach(function(n){n.parentNode.removeChild(n);});return;}
if(!(window.matchMedia&&matchMedia('(pointer:fine)').matches))return;
var tx=0,ty=0,cx=0,cy=0,raf=0;
function loop(){cx+=(tx-cx)*.07;cy+=(ty-cy)*.07;svg.style.setProperty('--mx',cx.toFixed(3));svg.style.setProperty('--my',cy.toFixed(3));
 raf=(Math.abs(tx-cx)+Math.abs(ty-cy)>.003)?requestAnimationFrame(loop):0;}
window.addEventListener('pointermove',function(e){tx=(e.clientX/window.innerWidth-.5)*2;ty=(e.clientY/window.innerHeight-.5)*2;if(!raf)raf=requestAnimationFrame(loop);},{passive:true});
})();
